FILE = "05-02-causal-fairness-use.vi.md"
PAIRS = [
("""Ngoài ra, mức nguy cơ và lợi ích của can thiệp có thể khác nhau, như các thực nghiệm thực địa về giữ chân khách hàng đã cho thấy [20]. Vì vậy, quyết định liên hệ vẫn được hoãn lại. Bước tiếp theo là một đợt thí điểm ngẫu nhiên hóa có thời điểm gốc (time zero, mốc bắt đầu theo dõi chung cho mọi sinh viên) là thời điểm chốt dữ liệu, khi sinh viên bắt đầu đủ điều kiện vào danh sách [44]; trong đợt thí điểm, các lần liên hệ và kết quả được ghi nhận cùng nhau.""",
 """Ngoài ra, mức nguy cơ và lợi ích nhận được từ can thiệp có thể không đi cùng nhau: người có nguy cơ cao nhất chưa chắc được lợi nhiều nhất, như các thực nghiệm thực địa về giữ chân khách hàng đã cho thấy [20]. Vì vậy, việc chọn hình thức liên hệ và mọi cách xếp hạng theo lợi ích kỳ vọng của việc liên hệ vẫn được hoãn; AQ4 chỉ cung cấp danh sách cho biết nên liên hệ sinh viên nào trước (D1). Bước tiếp theo là một đợt thí điểm ngẫu nhiên hóa. Thời điểm gốc (time zero) của đợt thí điểm, tức mốc bắt đầu theo dõi chung cho mọi sinh viên, là thời điểm chốt dữ liệu, khi sinh viên bắt đầu đủ điều kiện vào danh sách [44]. Trong đợt thí điểm, các lần liên hệ và kết quả được ghi nhận cùng nhau."""),
("""Sinh viên bị đánh dấu được chuyển sang hoạt động hỗ trợ; việc đánh dấu hết hiệu lực khi kỳ mở kết thúc. Lý do là sinh viên bị đánh dấu cần có cơ hội chứng minh dự báo là sai [45], còn nhãn gắn cho sinh viên không được làm thiên lệch cách cán bộ nhìn nhận sinh viên đó [46].""",
 """Đối với từng sinh viên trong danh sách, dấu cảnh báo chỉ dẫn đến hoạt động hỗ trợ và hết hiệu lực khi kỳ mở kết thúc. Quy định này bảo đảm sinh viên bị đánh dấu có cơ hội chứng minh dự báo là sai [45], đồng thời nhãn gắn cho sinh viên không làm thiên lệch cách cán bộ nhìn nhận sinh viên đó [46]."""),
]
